import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    s = input_data[1]

    best_sub = ""

    for length in range(1, n // 2 + 1):
        found = False
        for i in range(n - length * 2 + 1):
            sub = s[i:i+length]
            j = s.find(sub, i + length)
            if j != -1:
                if len(sub) > len(best_sub):
                    best_sub = sub
                    found = True
                elif len(sub) == len(best_sub) and best_sub:
                    pass
                break

        if found and len(best_sub) == length:
            break

    if best_sub:
        print(best_sub)
    else:
        print("-1")

if __name__ == "__main__":
    solve()
